PRAGMA foreign_keys = ON;
CREATE TABLE users (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'author',status TEXT NOT NULL DEFAULT 'active',last_login_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categories (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,description TEXT,status TEXT NOT NULL DEFAULT 'active',meta_title TEXT,meta_description TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE redirects (id INTEGER PRIMARY KEY AUTOINCREMENT,from_path TEXT NOT NULL UNIQUE,to_path TEXT NOT NULL,status_code INTEGER NOT NULL DEFAULT 301,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE posts (id INTEGER PRIMARY KEY AUTOINCREMENT,author_id INTEGER,category_id INTEGER,title TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,excerpt TEXT,content TEXT NOT NULL,featured_image TEXT,featured_image_alt TEXT,meta_title TEXT,meta_description TEXT,focus_keyword TEXT,secondary_keywords TEXT,canonical_url TEXT,robots TEXT NOT NULL DEFAULT 'index,follow',og_title TEXT,og_description TEXT,og_image TEXT,schema_json TEXT,status TEXT NOT NULL DEFAULT 'draft',published_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(author_id) REFERENCES users(id),FOREIGN KEY(category_id) REFERENCES categories(id));
CREATE TABLE audit_logs (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id INTEGER,details TEXT,ip_address TEXT,user_agent TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
